import 'package:flutter/material.dart';

/// My-Care 디자인 시스템 컬러 토큰
/// 의료적 신뢰감(Clinical Vitality)을 상징하는 Deep Teal을 메인으로 사용합니다.
abstract final class AppColors {
  // Brand Primary (Vital Teal)
  static const Color primary = Color(0xFF007A87);
  static const Color primaryContainer = Color(0xFFC7E7EC);
  static const Color onPrimary = Color(0xFFFFFFFF);
  static const Color onPrimaryContainer = Color(0xFF002024);

  // Secondary (Calm Sage / Soft Green)
  static const Color secondary = Color(0xFF386A63);
  static const Color secondaryContainer = Color(0xFFBCECE3);
  static const Color onSecondary = Color(0xFFFFFFFF);
  static const Color onSecondaryContainer = Color(0xFF00201C);

  // Accent / Clinical Warning & Highlights
  static const Color amberHighlight = Color(0xFFD97706);
  static const Color amberContainer = Color(0xFFFEF3C7);
  static const Color redAlert = Color(0xFFDC2626);
  static const Color redContainer = Color(0xFFFEE2E2);

  // Neutral & Surfaces (Clean Medical Paper)
  static const Color surface = Color(0xFFF8FAFC);
  static const Color surfaceContainer = Color(0xFFFFFFFF);
  static const Color surfaceContainerHigh = Color(0xFFF1F5F9);
  static const Color outline = Color(0xFFCBD5E1);
  static const Color outlineVariant = Color(0xFFE2E8F0);

  // Text colors
  static const Color textPrimary = Color(0xFF0F172A);
  static const Color textSecondary = Color(0xFF475569);
  static const Color textTertiary = Color(0xFF94A3B8);
}

import 'package:flutter/material.dart';
import 'app_colors.dart';

/// Android & iOS 양대 플랫폼에 최적화된 My-Care M3 테마
abstract final class AppTheme {
  static ThemeData get lightTheme {
    final colorScheme = ColorScheme.fromSeed(
      seedColor: AppColors.primary,
      brightness: Brightness.light,
      primary: AppColors.primary,
      surface: AppColors.surface,
      surfaceContainer: AppColors.surfaceContainer,
      outline: AppColors.outline,
      outlineVariant: AppColors.outlineVariant,
    );

    return ThemeData(
      useMaterial3: true,
      colorScheme: colorScheme,
      scaffoldBackgroundColor: AppColors.surface,

      // Cross-platform Page Transitions (iOS Swipe back & Android M3 Zoom)
      pageTransitionsTheme: const PageTransitionsTheme(
        builders: {
          TargetPlatform.iOS: CupertinoPageTransitionsBuilder(),
          TargetPlatform.android: ZoomPageTransitionsBuilder(),
          TargetPlatform.macOS: CupertinoPageTransitionsBuilder(),
          TargetPlatform.linux: ZoomPageTransitionsBuilder(),
        },
      ),

      // App Bar Theme
      appBarTheme: const AppBarTheme(
        backgroundColor: AppColors.surface,
        elevation: 0,
        scrolledUnderElevation: 0.5,
        centerTitle: false,
        titleTextStyle: TextStyle(
          color: AppColors.textPrimary,
          fontSize: 20,
          fontWeight: FontWeight.w700,
          letterSpacing: -0.5,
        ),
        iconTheme: IconThemeData(color: AppColors.textPrimary),
      ),

      // Card Theme (M3 Outlined & Tonal)
      cardTheme: CardTheme(
        color: AppColors.surfaceContainer,
        elevation: 0,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(16),
          side: const BorderSide(color: AppColors.outlineVariant, width: 1.2),
        ),
        margin: EdgeInsets.zero,
      ),

      // FilledButton Theme (48dp height minimum, rounded)
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(
          backgroundColor: AppColors.primary,
          foregroundColor: AppColors.onPrimary,
          minimumSize: const Size.fromHeight(54),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(14),
          ),
          textStyle: const TextStyle(
            fontSize: 16,
            fontWeight: FontWeight.w600,
            letterSpacing: -0.3,
          ),
          elevation: 0,
        ),
      ),

      // Chip Theme
      chipTheme: ChipThemeData(
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(10),
        ),
        side: const BorderSide(color: AppColors.outlineVariant, width: 1),
        labelStyle: const TextStyle(
          fontSize: 14,
          fontWeight: FontWeight.w500,
          color: AppColors.textPrimary,
        ),
      ),

      // Typography
      textTheme: const TextTheme(
        headlineLarge: TextStyle(
          fontSize: 28,
          fontWeight: FontWeight.w800,
          letterSpacing: -0.8,
          color: AppColors.textPrimary,
          height: 1.3,
        ),
        headlineMedium: TextStyle(
          fontSize: 22,
          fontWeight: FontWeight.w700,
          letterSpacing: -0.6,
          color: AppColors.textPrimary,
          height: 1.3,
        ),
        titleLarge: TextStyle(
          fontSize: 18,
          fontWeight: FontWeight.w700,
          letterSpacing: -0.4,
          color: AppColors.textPrimary,
        ),
        titleMedium: TextStyle(
          fontSize: 15,
          fontWeight: FontWeight.w600,
          letterSpacing: -0.3,
          color: AppColors.textPrimary,
        ),
        bodyLarge: TextStyle(
          fontSize: 15,
          fontWeight: FontWeight.w400,
          letterSpacing: -0.2,
          color: AppColors.textSecondary,
          height: 1.45,
        ),
        bodyMedium: TextStyle(
          fontSize: 13,
          fontWeight: FontWeight.w400,
          letterSpacing: -0.2,
          color: AppColors.textSecondary,
          height: 1.4,
        ),
        labelSmall: TextStyle(
          fontSize: 11,
          fontWeight: FontWeight.w600,
          letterSpacing: 0.2,
          color: AppColors.textTertiary,
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

/// 6대 대사 질환 정의 및 임상 메타데이터
enum ConditionType {
  prediabetes(
    id: 'prediabetes',
    name: '전당뇨',
    badge: '식후 골든타임',
    description: '식후 30~60분 시점 걷기로 혈당 스파이크 억제',
    clinicalFocus: '하체 대근육(허벅지)을 활용해 인슐린 비의존성 포도당 흡수를 촉진합니다.',
    icon: Icons.bloodtype_outlined,
  ),
  fattyLiver(
    id: 'fatty_liver',
    name: '지방간',
    badge: '내장지방 연소',
    description: '40분 이상 중등도 유산소로 간 내 지방산 산화',
    clinicalFocus: '내장지방 감소를 위해 최소 30~45분 지속 가능한 110 SPM 속도를 유지합니다.',
    icon: Icons.monitor_heart_outlined,
  ),
  hypertension(
    id: 'hypertension',
    name: '고혈압',
    badge: '발살바 호흡 금기',
    description: '숨 참지 않는 부드러운 저중량 다반복 머신 운동',
    clinicalFocus: '혈압 급상승을 막기 위해 무거운 프리웨이트 대신 머신과 지속 호흡을 권장합니다.',
    icon: Icons.favorite_outline,
  ),
  dyslipidemia(
    id: 'dyslipidemia',
    name: '고지혈증',
    badge: '지질 개선',
    description: 'HDL 증가와 중성지방 감소를 위한 45분 이상 유산소',
    clinicalFocus: '지방 대사 효소 활성화를 위해 충분한 시간의 지속 유산소가 핵심입니다.',
    icon: Icons.water_drop_outlined,
  ),
  obesity(
    id: 'obesity',
    name: '비만/복부비만',
    badge: '관절 보호',
    description: '무릎 관절 부담을 줄이는 충격 분산 유산소',
    clinicalFocus: '과체중으로 인한 무릎·발목 관절을 보호하며 점진적으로 활동량을 늘립니다.',
    icon: Icons.accessibility_new_outlined,
  ),
  gout(
    id: 'gout',
    name: '통풍',
    badge: '젖산 억제',
    description: '요산 배출을 돕는 저~중등도 운동 (고강도 금기)',
    clinicalFocus: '과도한 젖산 축적으로 인한 요산 배출 방해를 막기 위해 고강도 무산소를 피합니다.',
    icon: Icons.healing_outlined,
  );

  const ConditionType({
    required this.id,
    required this.name,
    required this.badge,
    required this.description,
    required this.clinicalFocus,
    required this.icon,
  });

  final String id;
  final String name;
  final String badge;
  final String description;
  final String clinicalFocus;
  final IconData icon;
}

/// 운동 선호 환경
enum ExerciseEnvironment {
  all(id: 'all', label: '전체 (어디서나)', icon: Icons.public_outlined),
  gym(id: 'gym', label: '헬스장 (기구 중심)', icon: Icons.fitness_center_outlined),
  home(id: 'home', label: '홈트레이닝 (맨몸)', icon: Icons.home_outlined);

  const ExerciseEnvironment({
    required this.id,
    required this.label,
    required this.icon,
  });

  final String id;
  final String label;
  final IconData icon;
}

import 'package:flutter/foundation.dart';
import '../../domain/model/condition_type.dart';

/// 온보딩 화면의 불변 상태(State)
class OnboardingState {
  const OnboardingState({
    this.selectedConditions = const <ConditionType>{},
    this.environment = ExerciseEnvironment.all,
    this.isSubmitting = false,
  });

  final Set<ConditionType> selectedConditions;
  final ExerciseEnvironment environment;
  final bool isSubmitting;

  bool get canProceed => selectedConditions.isNotEmpty;

  /// 복수 질환 선택 시 실시간 결합 처방 하이라이트 요약
  List<String> get clinicalHighlights {
    if (selectedConditions.isEmpty) return const [];
    final highlights = <String>[];

    if (selectedConditions.contains(ConditionType.prediabetes)) {
      highlights.add('식후 30~60분 이내 걷기 골든타임 적용');
    }
    if (selectedConditions.contains(ConditionType.fattyLiver)) {
      highlights.add('내장지방 산화를 위한 40분 이상 지속 유산소 권장');
    }
    if (selectedConditions.contains(ConditionType.hypertension)) {
      highlights.add('발살바 호흡 차단 및 안전한 머신 서킷 우선');
    }
    if (selectedConditions.contains(ConditionType.dyslipidemia)) {
      highlights.add('지질 대사 개선을 위한 중강도 인터벌 세팅');
    }
    if (selectedConditions.contains(ConditionType.obesity)) {
      highlights.add('체중 부하를 분산하는 저충격 관절 보호 모드');
    }
    if (selectedConditions.contains(ConditionType.gout)) {
      highlights.add('젖산 축적 방지를 위해 저~중등도 강도 유지');
    }

    return highlights;
  }

  OnboardingState copyWith({
    Set<ConditionType>? selectedConditions,
    ExerciseEnvironment? environment,
    bool? isSubmitting,
  }) {
    return OnboardingState(
      selectedConditions: selectedConditions ?? this.selectedConditions,
      environment: environment ?? this.environment,
      isSubmitting: isSubmitting ?? this.isSubmitting,
    );
  }
}

/// 온보딩 화면의 이벤트 액션
sealed class OnboardingAction {
  const OnboardingAction();
}

final class ToggleConditionAction extends OnboardingAction {
  const ToggleConditionAction(this.condition);
  final ConditionType condition;
}

final class SelectEnvironmentAction extends OnboardingAction {
  const SelectEnvironmentAction(this.environment);
  final ExerciseEnvironment environment;
}

final class SubmitOnboardingAction extends OnboardingAction {
  const SubmitOnboardingAction();
}

/// MVI 패턴의 Onboarding ViewModel (ChangeNotifier 기반)
class OnboardingViewModel extends ChangeNotifier {
  OnboardingViewModel({OnboardingState initialState = const OnboardingState()})
      : _state = initialState;

  OnboardingState _state;
  OnboardingState get state => _state;

  void onAction(OnboardingAction action) {
    switch (action) {
      case ToggleConditionAction(:final condition):
        final updated = Set<ConditionType>.from(_state.selectedConditions);
        if (updated.contains(condition)) {
          updated.remove(condition);
        } else {
          updated.add(condition);
        }
        _state = _state.copyWith(selectedConditions: updated);
        notifyListeners();

      case SelectEnvironmentAction(:final environment):
        _state = _state.copyWith(environment: environment);
        notifyListeners();

      case SubmitOnboardingAction():
        // 제출 및 처방 대시보드로 이동 준비
        _state = _state.copyWith(isSubmitting: true);
        notifyListeners();
    }
  }
}

import 'package:flutter/material.dart';
import '../../../domain/model/condition_type.dart';
import '../../../ui/app_colors.dart';

/// 질환 선택 카드 컴포넌트
class ConditionCard extends StatelessWidget {
  const ConditionCard({
    super.key,
    required this.condition,
    required this.isSelected,
    required this.onTap,
  });

  final ConditionType condition;
  final bool isSelected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(16),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 180),
        curve: Curves.easeInOut,
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: isSelected
              ? AppColors.primaryContainer.withValues(alpha: 0.3)
              : AppColors.surfaceContainer,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(
            color: isSelected ? AppColors.primary : AppColors.outlineVariant,
            width: isSelected ? 2 : 1.2,
          ),
          boxShadow: isSelected
              ? [
                  BoxShadow(
                    color: AppColors.primary.withValues(alpha: 0.08),
                    blurRadius: 10,
                    offset: const Offset(0, 4),
                  ),
                ]
              : null,
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 질환 아이콘 (M3 Tonal Circle)
            Container(
              width: 44,
              height: 44,
              decoration: BoxDecoration(
                color: isSelected
                    ? AppColors.primary
                    : AppColors.surfaceContainerHigh,
                shape: BoxShape.circle,
              ),
              child: Icon(
                condition.icon,
                color: isSelected ? AppColors.onPrimary : AppColors.primary,
                size: 22,
              ),
            ),
            const SizedBox(width: 14),

            // 텍스트 정보 (질환명 + 배지 + 설명)
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Text(
                        condition.name,
                        style: theme.textTheme.titleMedium?.copyWith(
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      const SizedBox(width: 8),
                      // 임상 특징 배지
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 8,
                          vertical: 2.5,
                        ),
                        decoration: BoxDecoration(
                          color: isSelected
                              ? AppColors.primary.withValues(alpha: 0.15)
                              : AppColors.surfaceContainerHigh,
                          borderRadius: BorderRadius.circular(6),
                        ),
                        child: Text(
                          condition.badge,
                          style: TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w600,
                            color: isSelected
                                ? AppColors.primary
                                : AppColors.textSecondary,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 5),
                  Text(
                    condition.description,
                    style: theme.textTheme.bodyMedium,
                  ),
                ],
              ),
            ),
            const SizedBox(width: 8),

            // 체크 인디케이터
            Container(
              width: 24,
              height: 24,
              margin: const EdgeInsets.only(top: 2),
              decoration: BoxDecoration(
                color: isSelected ? AppColors.primary : Colors.transparent,
                shape: BoxShape.circle,
                border: Border.all(
                  color: isSelected
                      ? AppColors.primary
                      : AppColors.outline,
                  width: 1.5,
                ),
              ),
              child: isSelected
                  ? const Icon(
                      Icons.check,
                      color: AppColors.onPrimary,
                      size: 16,
                    )
                  : null,
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import '../../../ui/app_colors.dart';

/// 선택된 다중 질환의 실시간 임상 결합 요약 배너
class ClinicalHighlightsBanner extends StatelessWidget {
  const ClinicalHighlightsBanner({
    super.key,
    required this.highlights,
  });

  final List<String> highlights;

  @override
  Widget build(BuildContext context) {
    if (highlights.isEmpty) return const SizedBox.shrink();

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: AppColors.secondaryContainer.withValues(alpha: 0.35),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: AppColors.secondary.withValues(alpha: 0.3),
          width: 1,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(
                Icons.health_and_safety_outlined,
                color: AppColors.secondary,
                size: 20,
              ),
              const SizedBox(width: 8),
              Text(
                '복수 질환 맞춤형 결합 원칙',
                style: TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w700,
                  color: AppColors.secondary,
                  letterSpacing: -0.3,
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          ...highlights.map(
            (point) => Padding(
              padding: const EdgeInsets.only(bottom: 6),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    '• ',
                    style: TextStyle(
                      color: AppColors.secondary,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  Expanded(
                    child: Text(
                      point,
                      style: const TextStyle(
                        fontSize: 13,
                        color: AppColors.textPrimary,
                        height: 1.35,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import '../../../domain/model/condition_type.dart';
import '../../../ui/app_colors.dart';

/// 선호 운동 환경 선택 세그먼트
class EnvironmentSelector extends StatelessWidget {
  const EnvironmentSelector({
    super.key,
    required this.selected,
    required this.onSelected,
  });

  final ExerciseEnvironment selected;
  final ValueChanged<ExerciseEnvironment> onSelected;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Text(
          '운동 환경 선택',
          style: TextStyle(
            fontSize: 16,
            fontWeight: FontWeight.w700,
            color: AppColors.textPrimary,
            letterSpacing: -0.4,
          ),
        ),
        const SizedBox(height: 10),
        Row(
          children: ExerciseEnvironment.values.map((env) {
            final isSelected = selected == env;
            return Expanded(
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 4),
                child: InkWell(
                  onTap: () => onSelected(env),
                  borderRadius: BorderRadius.circular(12),
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 150),
                    padding: const EdgeInsets.symmetric(vertical: 12),
                    decoration: BoxDecoration(
                      color: isSelected
                          ? AppColors.primary
                          : AppColors.surfaceContainer,
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(
                        color: isSelected
                            ? AppColors.primary
                            : AppColors.outlineVariant,
                        width: 1.2,
                      ),
                    ),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Icon(
                          env.icon,
                          size: 20,
                          color: isSelected
                              ? AppColors.onPrimary
                              : AppColors.textSecondary,
                        ),
                        const SizedBox(height: 6),
                        Text(
                          env.label.split(' ')[0], // '전체', '헬스장', '홈트레이닝'
                          style: TextStyle(
                            fontSize: 13,
                            fontWeight: isSelected
                                ? FontWeight.w700
                                : FontWeight.w500,
                            color: isSelected
                                ? AppColors.onPrimary
                                : AppColors.textSecondary,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            );
          }).toList(),
        ),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import '../../domain/model/condition_type.dart';
import '../../ui/app_colors.dart';
import 'onboarding_view_model.dart';
import 'widgets/clinical_highlights_banner.dart';
import 'widgets/condition_card.dart';
import 'widgets/environment_selector.dart';

/// Onboarding Root: ViewModel 주입 및 상태 구독
class OnboardingRoot extends StatefulWidget {
  const OnboardingRoot({super.key});

  @override
  State<OnboardingRoot> createState() => _OnboardingRootState();
}

class _OnboardingRootState extends State<OnboardingRoot> {
  late final OnboardingViewModel _viewModel;

  @override
  void initState() {
    super.initState();
    _viewModel = OnboardingViewModel();
  }

  @override
  void dispose() {
    _viewModel.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: _viewModel,
      builder: (context, _) {
        return OnboardingScreen(
          state: _viewModel.state,
          onAction: _viewModel.onAction,
        );
      },
    );
  }
}

/// Onboarding Screen: 순수 StatelessWidget UI
class OnboardingScreen extends StatelessWidget {
  const OnboardingScreen({
    super.key,
    required this.state,
    required this.onAction,
  });

  final OnboardingState state;
  final ValueChanged<OnboardingAction> onAction;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return Scaffold(
      appBar: AppBar(
        title: const Text('My-Care'),
      ),
      body: SafeArea(
        child: Column(
          children: [
            Expanded(
              child: ListView(
                padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
                children: [
                  // 상단 안내 헤더
                  Text(
                    '맞춤 대사 운동 처방',
                    style: TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w700,
                      color: AppColors.primary,
                      letterSpacing: 0.2,
                    ),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    '관리 중이거나 주의가 필요한\n질환을 모두 선택해 주세요',
                    style: theme.textTheme.headlineMedium,
                  ),
                  const SizedBox(height: 8),
                  Text(
                    '선택하신 질환들의 임상 가이드라인을 교차 분석하여\n무리 없는 운동 타이밍과 강도를 설계해 드립니다.',
                    style: theme.textTheme.bodyLarge,
                  ),
                  const SizedBox(height: 24),

                  // 6대 질환 카드 리스트
                  ...ConditionType.values.map((condition) {
                    final isSelected = state.selectedConditions.contains(condition);
                    return Padding(
                      padding: const EdgeInsets.only(bottom: 12),
                      child: ConditionCard(
                        condition: condition,
                        isSelected: isSelected,
                        onTap: () => onAction(ToggleConditionAction(condition)),
                      ),
                    );
                  }),

                  const SizedBox(height: 12),

                  // 운동 선호 환경
                  EnvironmentSelector(
                    selected: state.environment,
                    onSelected: (env) => onAction(SelectEnvironmentAction(env)),
                  ),

                  const SizedBox(height: 20),

                  // 실시간 복수 질환 결합 처방 하이라이트 배너
                  ClinicalHighlightsBanner(
                    highlights: state.clinicalHighlights,
                  ),

                  const SizedBox(height: 32),
                ],
              ),
            ),

            // 하단 고정 CTA 버튼
            _BottomCtaBar(
              canProceed: state.canProceed,
              selectedCount: state.selectedConditions.length,
              isSubmitting: state.isSubmitting,
              onSubmit: () => onAction(const SubmitOnboardingAction()),
            ),
          ],
        ),
      ),
    );
  }
}

class _BottomCtaBar extends StatelessWidget {
  const _BottomCtaBar({
    required this.canProceed,
    required this.selectedCount,
    required this.isSubmitting,
    required this.onSubmit,
  });

  final bool canProceed;
  final int selectedCount;
  final bool isSubmitting;
  final VoidCallback onSubmit;

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.fromLTRB(20, 12, 20, 16),
      decoration: BoxDecoration(
        color: AppColors.surfaceContainer,
        border: const Border(
          top: BorderSide(color: AppColors.outlineVariant, width: 1),
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.04),
            blurRadius: 10,
            offset: const Offset(0, -3),
          ),
        ],
      ),
      child: FilledButton(
        onPressed: canProceed && !isSubmitting ? onSubmit : null,
        style: FilledButton.styleFrom(
          backgroundColor: canProceed ? AppColors.primary : AppColors.outlineVariant,
          foregroundColor: canProceed ? AppColors.onPrimary : AppColors.textTertiary,
        ),
        child: isSubmitting
            ? const SizedBox(
                width: 22,
                height: 22,
                child: CircularProgressIndicator.adaptive(
                  strokeWidth: 2.5,
                  valueColor: AlwaysStoppedAnimation(Colors.white),
                ),
              )
            : Text(
                canProceed
                    ? '$selectedCount개 질환 맞춤 운동 처방 받기'
                    : '관리 중인 질환을 1개 이상 선택해 주세요',
              ),
      ),
    );
  }
}

