import 'dart:async';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

class WalkingState {
  const WalkingState({
    required this.targetSpm,
    required this.targetDurationMinutes,
    this.elapsedSeconds = 0,
    this.isActive = true,
    this.isCompleted = false,
  });

  final int targetSpm;
  final int targetDurationMinutes;
  final int elapsedSeconds;
  final bool isActive;
  final bool isCompleted;

  int get targetSeconds => targetDurationMinutes * 60;
  int get remainingSeconds => (targetSeconds - elapsedSeconds).clamp(0, targetSeconds);
  double get progress => targetSeconds > 0 ? (elapsedSeconds / targetSeconds).clamp(0.0, 1.0) : 0.0;

  // 추정 걸음 수 및 소비 칼로리 (표준 대사량 기준)
  int get estimatedSteps => ((elapsedSeconds * targetSpm) / 60).round();
  int get estimatedCalories => (estimatedSteps * 0.038).round();

  String get formattedElapsed {
    final m = (elapsedSeconds ~/ 60).toString().padLeft(2, '0');
    final s = (elapsedSeconds % 60).toString().padLeft(2, '0');
    return '$m:$s';
  }

  String get formattedRemaining {
    final m = (remainingSeconds ~/ 60).toString().padLeft(2, '0');
    final s = (remainingSeconds % 60).toString().padLeft(2, '0');
    return '$m:$s';
  }

  WalkingState copyWith({
    int? targetSpm,
    int? targetDurationMinutes,
    int? elapsedSeconds,
    bool? isActive,
    bool? isCompleted,
  }) {
    return WalkingState(
      targetSpm: targetSpm ?? this.targetSpm,
      targetDurationMinutes: targetDurationMinutes ?? this.targetDurationMinutes,
      elapsedSeconds: elapsedSeconds ?? this.elapsedSeconds,
      isActive: isActive ?? this.isActive,
      isCompleted: isCompleted ?? this.isCompleted,
    );
  }
}

sealed class WalkingAction {
  const WalkingAction();
}

final class TogglePlayPauseAction extends WalkingAction {
  const TogglePlayPauseAction();
}

final class AdjustSpmAction extends WalkingAction {
  const AdjustSpmAction(this.delta);
  final int delta; // e.g. +5 or -5
}

final class TickAction extends WalkingAction {
  const TickAction();
}

final class FinishWalkingAction extends WalkingAction {
  const FinishWalkingAction();
}

class WalkingViewModel extends ChangeNotifier {
  WalkingViewModel({
    required int initialSpm,
    required int initialDurationMinutes,
  }) : _state = WalkingState(
          targetSpm: initialSpm,
          targetDurationMinutes: initialDurationMinutes,
        ) {
    _startTimer();
  }

  WalkingState _state;
  WalkingState get state => _state;
  Timer? _timer;

  void onAction(WalkingAction action) {
    switch (action) {
      case TogglePlayPauseAction():
        if (_state.isActive) {
          _timer?.cancel();
          _state = _state.copyWith(isActive: false);
        } else {
          _startTimer();
          _state = _state.copyWith(isActive: true);
        }
        notifyListeners();

      case AdjustSpmAction(:final delta):
        final newSpm = (_state.targetSpm + delta).clamp(80, 160);
        _state = _state.copyWith(targetSpm: newSpm);
        HapticFeedback.selectionClick();
        notifyListeners();

      case TickAction():
        final newElapsed = _state.elapsedSeconds + 1;
        final completed = newElapsed >= _state.targetSeconds;
        if (completed && !_state.isCompleted) {
          _timer?.cancel();
          _state = _state.copyWith(
            elapsedSeconds: newElapsed,
            isActive: false,
            isCompleted: true,
          );
        } else {
          _state = _state.copyWith(elapsedSeconds: newElapsed);
        }
        notifyListeners();

      case FinishWalkingAction():
        _timer?.cancel();
        _state = _state.copyWith(isActive: false, isCompleted: true);
        notifyListeners();
    }
  }

  void _startTimer() {
    _timer?.cancel();
    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      onAction(const TickAction());
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }
}

import 'package:flutter/material.dart';
import '../../../ui/app_colors.dart';

/// 현재 SPM 주기에 맞춰 부드럽게 펄스(박자)를 시각화하는 메트로놈 위젯
class WalkingRhythmVisualizer extends StatefulWidget {
  const WalkingRhythmVisualizer({
    super.key,
    required this.spm,
    required this.isActive,
  });

  final int spm;
  final bool isActive;

  @override
  State<WalkingRhythmVisualizer> createState() => _WalkingRhythmVisualizerState();
}

class _WalkingRhythmVisualizerState extends State<WalkingRhythmVisualizer>
    with SingleTickerProviderStateMixin {
  late AnimationController _pulseController;
  late Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initController();
  }

  void _initController() {
    // 1회 박동 시간(초) = 60 / SPM
    final beatDurationMs = (60000 / widget.spm).round();

    _pulseController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: beatDurationMs),
    );

    _scaleAnimation = Tween<double>(begin: 0.95, end: 1.05).animate(
      CurvedAnimation(parent: _pulseController, curve: Curves.easeInOut),
    );

    if (widget.isActive) {
      _pulseController.repeat(reverse: true);
    }
  }

  @override
  void didUpdateWidget(covariant WalkingRhythmVisualizer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.spm != widget.spm) {
      final beatDurationMs = (60000 / widget.spm).round();
      _pulseController.duration = Duration(milliseconds: beatDurationMs);
    }
    if (widget.isActive && !_pulseController.isAnimating) {
      _pulseController.repeat(reverse: true);
    } else if (!widget.isActive && _pulseController.isAnimating) {
      _pulseController.stop();
    }
  }

  @override
  void dispose() {
    _pulseController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _scaleAnimation,
      builder: (context, child) {
        final scale = widget.isActive ? _scaleAnimation.value : 1.0;

        return Center(
          child: Stack(
            alignment: Alignment.center,
            children: [
              // 바깥쪽 부드러운 펄스 링
              Container(
                width: 250 * scale,
                height: 250 * scale,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: AppColors.primary.withValues(alpha: 0.08),
                ),
              ),
              // 안쪽 메인 비트 원
              Container(
                width: 200,
                height: 200,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: AppColors.surfaceContainer,
                  border: Border.all(
                    color: widget.isActive
                        ? AppColors.primary
                        : AppColors.outlineVariant,
                    width: 3,
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: AppColors.primary.withValues(alpha: widget.isActive ? 0.15 : 0.04),
                      blurRadius: 20,
                      offset: const Offset(0, 8),
                    ),
                  ],
                ),
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    Icon(
                      Icons.directions_walk,
                      size: 28,
                      color: widget.isActive
                          ? AppColors.primary
                          : AppColors.textTertiary,
                    ),
                    const SizedBox(height: 6),
                    Text(
                      '${widget.spm}',
                      style: TextStyle(
                        fontSize: 48,
                        fontWeight: FontWeight.w900,
                        color: widget.isActive
                            ? AppColors.textPrimary
                            : AppColors.textTertiary,
                        letterSpacing: -2,
                        height: 1.0,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      'SPM (분당 걸음수)',
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w600,
                        color: widget.isActive
                            ? AppColors.primary
                            : AppColors.textTertiary,
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';
import '../../ui/app_colors.dart';
import 'walking_view_model.dart';
import 'widgets/walking_rhythm_visualizer.dart';

/// Walking Root: ViewModel 주입 및 상태 구독
class WalkingRoot extends StatefulWidget {
  const WalkingRoot({
    super.key,
    required this.targetSpm,
    required this.durationMinutes,
  });

  final int targetSpm;
  final int durationMinutes;

  @override
  State<WalkingRoot> createState() => _WalkingRootState();
}

class _WalkingRootState extends State<WalkingRoot> {
  late final WalkingViewModel _viewModel;

  @override
  void initState() {
    super.initState();
    _viewModel = WalkingViewModel(
      initialSpm: widget.targetSpm,
      initialDurationMinutes: widget.durationMinutes,
    );
  }

  @override
  void dispose() {
    _viewModel.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return ListenableBuilder(
      listenable: _viewModel,
      builder: (context, _) {
        final state = _viewModel.state;
        return WalkingScreen(
          state: state,
          onAction: _viewModel.onAction,
          onClose: () => _handleClose(context),
        );
      },
    );
  }

  void _handleClose(BuildContext context) {
    if (_viewModel.state.elapsedSeconds > 10 && !_viewModel.state.isCompleted) {
      showAdaptiveDialog(
        context: context,
        builder: (ctx) => AlertDialog.adaptive(
          title: const Text('운동 종료 확인'),
          content: const Text('지금 종료하시겠습니까? 오늘 기록된 시간과 걸음 수가 저장됩니다.'),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(ctx).pop(),
              child: const Text('계속하기'),
            ),
            TextButton(
              onPressed: () {
                Navigator.of(ctx).pop();
                Navigator.of(context).pop();
              },
              child: const Text('종료', style: TextStyle(color: AppColors.redAlert)),
            ),
          ],
        ),
      );
    } else {
      Navigator.of(context).pop();
    }
  }
}

/// Walking Screen: 순수 StatelessWidget UI
class WalkingScreen extends StatelessWidget {
  const WalkingScreen({
    super.key,
    required this.state,
    required this.onAction,
    required this.onClose,
  });

  final WalkingState state;
  final ValueChanged<WalkingAction> onAction;
  final VoidCallback onClose;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('실시간 워킹 코칭'),
        leading: IconButton(
          icon: const Icon(Icons.close),
          onPressed: onClose,
        ),
      ),
      body: SafeArea(
        child: Column(
          children: [
            // 1. 상단 목표 시간 프로그레스 바
            LinearProgressIndicator(
              value: state.progress,
              backgroundColor: AppColors.outlineVariant,
              valueColor: const AlwaysStoppedAnimation(AppColors.primary),
              minHeight: 4,
            ),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  Text(
                    '경과 ${state.formattedElapsed}',
                    style: const TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w600,
                      color: AppColors.textSecondary,
                    ),
                  ),
                  Text(
                    '목표 ${state.targetDurationMinutes}분',
                    style: const TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w700,
                      color: AppColors.primary,
                    ),
                  ),
                ],
              ),
            ),

            const Spacer(),

            // 2. 중앙 메트로놈 펄스 비트 시각화
            WalkingRhythmVisualizer(
              spm: state.targetSpm,
              isActive: state.isActive,
            ),
            const SizedBox(height: 16),

            // SPM 속도 미세 조절 버튼 (-5 / +5)
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                OutlinedButton.icon(
                  onPressed: () => onAction(const AdjustSpmAction(-5)),
                  icon: const Icon(Icons.remove, size: 16),
                  label: const Text('5 SPM 늦게'),
                  style: OutlinedButton.styleFrom(
                    visualDensity: VisualDensity.compact,
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(20),
                    ),
                  ),
                ),
                const SizedBox(width: 12),
                OutlinedButton.icon(
                  onPressed: () => onAction(const AdjustSpmAction(5)),
                  icon: const Icon(Icons.add, size: 16),
                  label: const Text('5 SPM 빠르게'),
                  style: OutlinedButton.styleFrom(
                    visualDensity: VisualDensity.compact,
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(20),
                    ),
                  ),
                ),
              ],
            ),

            const Spacer(),

            // 3. 실시간 운동 데이터 지표 (시간, 걸음수, 칼로리)
            Container(
              margin: const EdgeInsets.symmetric(horizontal: 20),
              padding: const EdgeInsets.symmetric(vertical: 16, horizontal: 20),
              decoration: BoxDecoration(
                color: AppColors.surfaceContainer,
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: AppColors.outlineVariant, width: 1),
              ),
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceAround,
                children: [
                  _StatItem(
                    label: '운동 시간',
                    value: state.formattedElapsed,
                    unit: '',
                  ),
                  Container(width: 1, height: 32, color: AppColors.outlineVariant),
                  _StatItem(
                    label: '추정 걸음',
                    value: '${state.estimatedSteps}',
                    unit: '보',
                  ),
                  Container(width: 1, height: 32, color: AppColors.outlineVariant),
                  _StatItem(
                    label: '소비 칼로리',
                    value: '${state.estimatedCalories}',
                    unit: 'kcal',
                  ),
                ],
              ),
            ),
            const SizedBox(height: 24),

            // 4. 하단 컨트롤러 (일시정지/재생 & 완료 버튼)
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 20),
              child: Row(
                children: [
                  // 운동 완료 버튼
                  Expanded(
                    flex: 1,
                    child: OutlinedButton(
                      onPressed: () => _showCompletionDialog(context),
                      style: OutlinedButton.styleFrom(
                        minimumSize: const Size.fromHeight(54),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(14),
                        ),
                      ),
                      child: const Text('운동 완료'),
                    ),
                  ),
                  const SizedBox(width: 12),
                  // 재생 / 일시정지 버튼
                  Expanded(
                    flex: 2,
                    child: FilledButton.icon(
                      onPressed: () => onAction(const TogglePlayPauseAction()),
                      icon: Icon(
                        state.isActive ? Icons.pause_rounded : Icons.play_arrow_rounded,
                        size: 22,
                      ),
                      label: Text(state.isActive ? '일시 정지' : '다시 걷기'),
                      style: FilledButton.styleFrom(
                        backgroundColor:
                            state.isActive ? AppColors.textPrimary : AppColors.primary,
                      ),
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 16),
          ],
        ),
      ),
    );
  }

  void _showCompletionDialog(BuildContext context) {
    showAdaptiveDialog(
      context: context,
      builder: (ctx) {
        return AlertDialog.adaptive(
          title: const Text('오늘의 워킹 완료! 🎉'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                '총 운동 시간: ${state.formattedElapsed}\n'
                '달성 걸음 수: 약 ${state.estimatedSteps}보\n'
                '소모 칼로리: 약 ${state.estimatedCalories} kcal\n\n'
                '규칙적인 SPM 걷기로 대사 질환 관리에 큰 효과를 거두셨습니다. 수분을 충분히 섭취해 주세요!',
                style: const TextStyle(fontSize: 14, height: 1.4),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.of(ctx).pop();
                Navigator.of(context).pop();
              },
              child: const Text('대시보드로 돌아가기'),
            ),
          ],
        );
      },
    );
  }
}

class _StatItem extends StatelessWidget {
  const _StatItem({
    required this.label,
    required this.value,
    required this.unit,
  });

  final String label;
  final String value;
  final String unit;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Text(
          label,
          style: const TextStyle(
            fontSize: 11.5,
            color: AppColors.textTertiary,
            fontWeight: FontWeight.w500,
          ),
        ),
        const SizedBox(height: 4),
        Row(
          crossAxisAlignment: CrossAxisAlignment.baseline,
          textBaseline: TextBaseline.alphabetic,
          children: [
            Text(
              value,
              style: const TextStyle(
                fontSize: 18,
                fontWeight: FontWeight.w800,
                color: AppColors.textPrimary,
              ),
            ),
            if (unit.isNotEmpty) ...[
              const SizedBox(width: 2),
              Text(
                unit,
                style: const TextStyle(
                  fontSize: 11,
                  color: AppColors.textSecondary,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ],
        ),
      ],
    );
  }
}

