                      shape: BoxShape.circle,
                      border: Border.all(
                        color: isToday
                            ? AppColors.primary
                            : (isCompleted
                                ? AppColors.primary
                                : AppColors.outlineVariant),
                        width: isToday ? 2 : 1,
                      ),
                    ),
                    child: Center(
                      child: isCompleted
                          ? const Icon(Icons.check, size: 20, color: AppColors.onPrimary)
                          : (isToday
                              ? Container(
                                  width: 8,
                                  height: 8,
                                  decoration: const BoxDecoration(
