import 'condition_type.dart';

/// 맞춤 운동 루틴 템플릿 모델
class RoutineTemplate {
  const RoutineTemplate({
    required this.id,
    required this.name,
    required this.environment,
    required this.conditionNames,
    required this.aerobicType, // 'treadmill' or 'walking'
    required this.aerobicDurationMinutes,
    required this.aerobicTargetSpm,
    required this.selectedExerciseNames,
    required this.targetSets,
    required this.createdAt,
    this.isPreset = false,
  });

  final String id;
  final String name;
  final ExerciseEnvironment environment;
  final List<String> conditionNames;
  final String aerobicType;
  final int aerobicDurationMinutes;
  final int aerobicTargetSpm;
  final List<String> selectedExerciseNames;
  final int targetSets;
  final DateTime createdAt;
  final bool isPreset;

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'name': name,
      'environment': environment.name,
      'conditionNames': conditionNames,
      'aerobicType': aerobicType,
      'aerobicDurationMinutes': aerobicDurationMinutes,
      'aerobicTargetSpm': aerobicTargetSpm,
      'selectedExerciseNames': selectedExerciseNames,
      'targetSets': targetSets,
      'createdAt': createdAt.toIso8601String(),
      'isPreset': isPreset,
    };
  }

  factory RoutineTemplate.fromJson(Map<String, dynamic> json) {
    return RoutineTemplate(
      id: json['id'] as String,
      name: json['name'] as String,
      environment: ExerciseEnvironment.values.firstWhere(
        (e) => e.name == json['environment'],
        orElse: () => ExerciseEnvironment.home,
      ),
      conditionNames: (json['conditionNames'] as List<dynamic>?)
              ?.map((e) => e.toString())
              .toList() ??
          [],
      aerobicType: json['aerobicType'] as String? ?? 'walking',
      aerobicDurationMinutes: json['aerobicDurationMinutes'] as int? ?? 30,
      aerobicTargetSpm: json['aerobicTargetSpm'] as int? ?? 115,
      selectedExerciseNames: (json['selectedExerciseNames'] as List<dynamic>?)
              ?.map((e) => e.toString())
              .toList() ??
          [],
      targetSets: json['targetSets'] as int? ?? 3,
      createdAt: json['createdAt'] != null
          ? DateTime.tryParse(json['createdAt'] as String) ?? DateTime.now()
          : DateTime.now(),
      isPreset: json['isPreset'] as bool? ?? false,
    );
  }

  RoutineTemplate copyWith({
    String? id,
    String? name,
    ExerciseEnvironment? environment,
    List<String>? conditionNames,
    String? aerobicType,
    int? aerobicDurationMinutes,
    int? aerobicTargetSpm,
    List<String>? selectedExerciseNames,
    int? targetSets,
    DateTime? createdAt,
    bool? isPreset,
  }) {
    return RoutineTemplate(
      id: id ?? this.id,
      name: name ?? this.name,
      environment: environment ?? this.environment,
      conditionNames: conditionNames ?? this.conditionNames,
      aerobicType: aerobicType ?? this.aerobicType,
      aerobicDurationMinutes:
          aerobicDurationMinutes ?? this.aerobicDurationMinutes,
      aerobicTargetSpm: aerobicTargetSpm ?? this.aerobicTargetSpm,
      selectedExerciseNames:
          selectedExerciseNames ?? this.selectedExerciseNames,
      targetSets: targetSets ?? this.targetSets,
      createdAt: createdAt ?? this.createdAt,
      isPreset: isPreset ?? this.isPreset,
    );
  }
}

import 'dart:convert';
import 'package:shared_preferences/shared_preferences.dart';
import '../../domain/model/condition_type.dart';
import '../../domain/model/routine_template.dart';

class RoutineTemplateRepository {
  const RoutineTemplateRepository();

  static const String _keyTemplates = 'my_care_routine_templates_v1';

  /// 저장된 템플릿 목록 조회 (비어있으면 기본 프리셋 2종 자동 제공)
  Future<List<RoutineTemplate>> getTemplates({
    Set<ConditionType>? conditions,
  }) async {
    final prefs = await SharedPreferences.getInstance();
    final rawList = prefs.getStringList(_keyTemplates);

    final templates = <RoutineTemplate>[];
    if (rawList != null && rawList.isNotEmpty) {
      for (final item in rawList) {
        try {
          final map = jsonDecode(item) as Map<String, dynamic>;
          templates.add(RoutineTemplate.fromJson(map));
        } catch (_) {}
      }
    }

    // 기본 프리셋 템플릿이 없으면 기본 추천 프리셋 2종 추가
    if (templates.isEmpty) {
      final presets = _createDefaultPresets();
      for (final p in presets) {
        await saveTemplate(p);
      }
      return presets;
    }

    return templates;
  }

  /// 템플릿 저장 (신규 등록 or 수정)
  Future<void> saveTemplate(RoutineTemplate template) async {
    final prefs = await SharedPreferences.getInstance();
    final rawList = prefs.getStringList(_keyTemplates) ?? <String>[];

    final existingIndex = rawList.indexWhere((item) {
      try {
        final map = jsonDecode(item) as Map<String, dynamic>;
        return map['id'] == template.id;
      } catch (_) {
        return false;
      }
    });

    final encoded = jsonEncode(template.toJson());
    if (existingIndex >= 0) {
      rawList[existingIndex] = encoded;
    } else {
      rawList.insert(0, encoded);
    }

    await prefs.setStringList(_keyTemplates, rawList);
  }

  /// 템플릿 삭제
  Future<void> deleteTemplate(String id) async {
    final prefs = await SharedPreferences.getInstance();
    final rawList = prefs.getStringList(_keyTemplates) ?? <String>[];

    rawList.removeWhere((item) {
      try {
        final map = jsonDecode(item) as Map<String, dynamic>;
        return map['id'] == id;
      } catch (_) {
        return false;
      }
    });

    await prefs.setStringList(_keyTemplates, rawList);
  }

  List<RoutineTemplate> _createDefaultPresets() {
    final now = DateTime.now();
    return [
      RoutineTemplate(
        id: 'preset_gym_metabolic',
        name: '⭐ [추천] 대사 케어 헬스장 루틴',
        environment: ExerciseEnvironment.gym,
        conditionNames: ['전당뇨', '고혈압', '비만'],
        aerobicType: 'treadmill',
        aerobicDurationMinutes: 40,
        aerobicTargetSpm: 115,
        selectedExerciseNames: [
          '시티드 레그프레스',
          '체스트 프레스 머신',
          '시티드 레그익스텐션 (저중량)',
          '랫풀다운 머신',
        ],
        targetSets: 3,
        createdAt: now,
        isPreset: true,
      ),
      RoutineTemplate(
        id: 'preset_home_glucose',
        name: '⭐ [추천] 식후 안심 홈트 루틴',
        environment: ExerciseEnvironment.home,
        conditionNames: ['전당뇨', '고혈압'],
        aerobicType: 'walking',
        aerobicDurationMinutes: 30,
        aerobicTargetSpm: 115,
        selectedExerciseNames: [
          '체어 스쿼트 (의자 스쿼트)',
          '카프 레이즈 (발뒤꿈치 들기)',
          '월 푸시업 (벽 짚고 밀기)',
          '월 싯 (벽 대고 버티기)',
        ],
        targetSets: 3,
        createdAt: now,
        isPreset: true,
      ),
    ];
  }
}

