                                  const SizedBox(width: 8),
                                  Text(
                                    '🏋️ 헬스장 (기구 운동)',
                                    style: TextStyle(
                                      fontSize: 13.5,
                                      fontWeight: FontWeight.w700,
                                      color: isGym
                                          ? AppColors.onPrimary
                                          : AppColors.textSecondary,
                                    ),
