                  const SizedBox(height: 6),
                  Text(
                    weekdayLabels[index],
                    style: TextStyle(
                      fontSize: 12,
                      fontWeight: isToday ? FontWeight.w800 : FontWeight.w500,
                      color:
                          isToday ? AppColors.primary : AppColors.textSecondary,
