    // 부위별 분류 (하체 / 상체 밀기 / 상체 당기기 및 코어)
    final lowerExercises = allExercises.where((e) {
      final t = '${e.name} ${e.target} ${e.category}'.toLowerCase();
      return t.contains('레그') ||
          t.contains('스쿼트') ||
          t.contains('하체') ||
          t.contains('카프') ||
          t.contains('뒤꿈치') ||
          t.contains('익스텐션') ||
          t.contains('브릿지') ||
          t.contains('데드리프트') ||
